from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import range, int, object
from time import sleep
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.counting import CountingPackets
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.capturing import SavingPackets
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from future import standard_library
from ute_common_store import Store
from ute_common_converter.to_number import to_int
from SSHLibrary import SSHClient
from robot.utils.robottime import timestr_to_secs
from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.rf_module.rf_module import RfModule
from taf.ul.trs_e2e_fw.lib.utils.cloud.cloud_interface import setup_CBTS_remote_access


standard_library.install_aliases()


class tcpdump(object):
    """Class provide mechanism for packets capturing on local or remote machine interface.

       This library supports multiple setups where each setup can be specified by **alias** argument for every keyword.

       This argument can be specified as follows:
       ::

           Setup tcpdump  interface=${ENB_TRS_INTERFACE}  log_dir=/home/ute  log_name=tcpdump_example_02  alias=example_02_eth3

       More examples are available in attached Robot Framework example files.


    Keywords
    ********
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.store = Store()
        self.ssh_client = None
        self.remote_conn = RemoteConnection()

    def setup_tcpdump(self, interface, log_dir='/tmp', log_name=None, snaplen=65535, pcap_size=None,
                      tcpdump_dir='/usr/bin', preferences=None, ssh_ip='localhost', ssh_username='ute',
                      ssh_password='ute', ssh_port=22, ssh_prompt='$ ', encoding='unicode-escape', sudo=False,
                      **kwargs):

        """Setup tcpdump library

        Library is working through SSH connection. Localhost is used as default destination.


        :param string interface:        Local or remote virtual machine interface which is used to packects capture.
        :param string log_dir:          Directory name where pcap file is stored.
        :param string log_name:         File name where packets are stored.
        :param integer snaplen:         Amount of data for each frame that is captured.
        :param string tcpdump_dir:       Path to dictionary where tcpdump is located.
        :param string preferences:      Preference setting to be overridden.
        :param string ssh_ip:           IP address of remote machine.
        :param string ssh_username:     Username for SSH authentication valid for remote machine.
        :param string ssh_password:     Password for SSH authentication valid for remote machine.
        :param integer ssh_port:        Port of SSH service available on remote machine.
        :param string ssh_prompt:       SSH prompt available after log in.
        :param string encoding:         Encoding to be used by SSH.
        """
        if kwargs.get('config_name'):
            connection_alias = 'internal_from_tcpudmp'
            if kwargs.get('fhnet_login_only') is not None:
                RfModule().rfmodule_setup(config_device=kwargs['config_name'],
                                          rfmod_inst_id=kwargs.get('rfmod_inst_id', 1),
                                          iprange=kwargs.get('iprange', None), fhnet_login_only=kwargs.get('fhnet_login_only'),
                                          alias=connection_alias)
            else:
                setup_CBTS_remote_access(remote_device=kwargs['config_name'], hop_list=kwargs['hop_list'],
                                         alias=connection_alias)
            ssh_client = connection_alias
        else:
            if kwargs.get('remote_lmp_ip'):
                remote_lmp_ip = kwargs.get('remote_lmp_ip')
                remote_lmp_user = kwargs.get('remote_lmp_user')
                remote_lmp_password = kwargs.get('remote_lmp_password')
                self.remote_conn.create_ssh_tunnel(remote_lmp_ip, 22, remote_lmp_user, remote_lmp_password, ssh_ip,
                                                   22, '0.0.0.0', 10022)
                ssh_ip = '0.0.0.0'
                ssh_port = 10022
            if self._encoding_exists():
                ssh_client = SSHClient(ssh_ip, port=ssh_port, prompt=ssh_prompt, timeout=10, encoding=encoding)
            else:
                ssh_client = SSHClient(ssh_ip, port=ssh_port, prompt=ssh_prompt, timeout=10)
            ssh_client = self._attempt_ssh_client_login(ssh_client, ssh_username, ssh_password, ssh_prompt)
        tcpdumps = self._build_dict_with_tcpdumps(ssh_client, tcpdump_dir, interface, log_dir, log_name, snaplen,
                                                  pcap_size, preferences, sudo)
        self.store.add(tcpdumps, alias=kwargs.get('alias'))

    def teardown_tcpdump(self, **kwargs):
        """Close and Cleanup tcpdump.
        """
        self._cleaner(self.store.get(alias=kwargs.get('alias')))
        self.store.remove(alias=kwargs.get('alias'))
        self.remote_conn.stop_ssh_tunnel()

    def teardown_all_aliases_for_tcpdump(self):
        """Close and Cleanup all tcpdump aliases.
        """
        self._out_of_scope()

    def start_capturing(self, capture_filter, sudo, log_dir=None, log_name=None, **kwargs):
        """Start collecting logs with capture filter.

        :param string capture_filter:   Capture filter definition       (equivalent -f in tcpdump).
        :param string log_dir:          Replaces log_dir passed in setup tcpdump until stop capturing KW is called
        :param string log_name:         Replaces log_name passed in setup tcpdump until stop capturing KW is called

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].start_logging(capture_filter, sudo, log_dir, log_name)

    def capture_packets_for_given_seconds(self, seconds, capture_filter='', log_dir=None, log_name=None, **kwargs):
        """Start collecting logs with capture filter and wait until command execution finish.

        :param string seconds:          Time duration of tcpdump execution (tcpdump -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition       (equivalent -f in tcpdump).
        :param string log_dir:          Replaces log_dir passed in setup tcpdump until stop capturing KW is called
        :param string log_name:         Replaces log_name passed in setup tcpdump until stop capturing KW is called

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].capture_packets_for_given_seconds(seconds,
                                                                                              capture_filter,
                                                                                              log_dir, log_name)

    def capture_given_packet_count_and_wait(self, packets, timeout=30, capture_filter='', log_dir=None,
                                            log_name=None, **kwargs):
        """Start capturing packets and wait until given packets are captured.

        :param string packets:          Number of packets to capture (tcpdump -c equivalent).
        :param string timeout:          Time duration for packet capture (tcpdump -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition   (tcpdump -f equivalent).
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].capture_given_packet_count_and_wait(packets, timeout,
                                                                                                capture_filter,
                                                                                                log_dir, log_name)

    def stop_capturing(self, **kwargs):
        """Stop collecting logs.

        """
        self.store.get(alias=kwargs.get('alias'))['saving'].stop_logging()

    def start_counting_packets(self, packet_filter, **kwargs):
        """Start counting packets with given packet filter.

        :param string packet_filter:        Packet filter definition       (equivalent -Y in tcpdump).

        """
        self.store.get(alias=kwargs.get('alias'))['counting'].start_counting(packet_filter)

    def stop_counting_packets(self, **kwargs):
        """Stop counting packets.

        """
        self.store.get(alias=kwargs.get('alias'))['counting'].stop_counting()

    def wait_for_given_packets_number(self, packet_number, timeout=120, **kwargs):
        """Wait until given packets are captured.

        :param integer packet_number:   Maximum number of packets to be captured.
        :param integer timeout:         Maximum number of seconds to wait for a given number of packets are captured.

        :raise: exception if captured packets are not equal packet_number before timeout.
        """

        timeout = timestr_to_secs(timeout)
        packet_number = to_int(packet_number)
        self.store.get(alias=kwargs.get('alias'))['counting'].wait_for_packets(packet_number, timeout)

    def read_pcap(self, packet_filter='', output_type='text', pcap_file_path=None, decode_as=None, sudo=False,
                  **kwargs):
        """Read pcap file and return it as string.

        :param string packet_filter:    Deep packet filter definition       (tcpdump -Y equivalent).
        :param string output_type:      Output form e.g pdml/text/lines     (tcpdump -T equivalent).
        :param string decode_as:        Decode as protocol                  (tcpdump -d equivalent)
        :param string pcap_file_path:   Pcap file path.

        :return:                        Packets matched with packet filter rules.
        :rtype:                         string
        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].read_pcap(packet_filter=packet_filter,
                                                                             output_type=output_type,
                                                                             decode_as=decode_as,
                                                                             pcap_file=pcap_file_path,
                                                                             sudo=sudo)

    def download_pcap_file(self, destination, sudo=False, **kwargs):
        """Copy pcap file to specified destination path on PC.

        :param string destination:          Destination file path.

        :return:                            Source and destination path.
        :rtype:                             tuple
        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].download_pcap(destination, sudo=sudo)

    def get_packets_count(self, packet_filter='', pcap_file_path=None, sudo=False, **kwargs):
        """Returns number of packets matched with the packet filter.

        :param string packet_filter:    Deep packet filter definition       (tcpdump -Y equivalent).
        :param string pcap_file_path:   Pcap file path.

        :return :                       Number of packets matched with packet filter rules.
        :rtype:                         integer

        """
        output = self.store.get(alias=kwargs.get('alias'))['saving'].read_pcap(packet_filter=packet_filter,
                                                                               output_type='lines',
                                                                               pcap_file=pcap_file_path, sudo=sudo)
        captured_packets = output.rstrip().split('\n')
        return int(len([_f for _f in captured_packets if _f]))
        # return int(len(filter(None, captured_packets)))

    def get_packet_number(self, **kwargs):
        """ Get number of packets collected by start_counting method.

        :return integer:        Amount of captured packets.
        :rtype:                 integer
        """
        return self.store.get(alias=kwargs.get('alias'))['counting'].get_packet_number()

    def lookup_message_flow(self, messages, pcap_file_path=None, **kwargs):
        """Search for messages in pcap file read in pdml format. Returns true if order and duplication is correct.

        :param list messages:                messages that will be checked.
        :param string pcap_file_path:        Pcap file path where messages will be searched.

        :return boolean:                True if messages are found in order and correct frequency else False.

        """
        return self.store.get(alias=kwargs.get('alias'))['saving'].lookup_message_flow(messages, pcap_file_path)

    def _encoding_exists(self):
        return 'encoding' in SSHClient.__init__.__code__.co_varnames
        # return 'encoding' in SSHClient.__init__.func_code.co_varnames

    def _cleaner(self, tcpdumps):
        for tcpdump in list(tcpdumps.values()):
            if tcpdump.pid is not None:
                tcpdump.stop_process()

    def _build_dict_with_tcpdumps(self, ssh_client, tcpdump_dir, interface, log_dir, log_name, snaplen, pcap_size,
                                  preferences, sudo):
        tcpdumps_dict = {'saving': SavingPackets(ssh_client, tcpdump_dir, interface, log_dir, sudo, log_name, snaplen,
                                                 pcap_size, preferences),
                        'counting': CountingPackets(ssh_client, tcpdump_dir, interface, sudo, log_dir, snaplen,
                                                    preferences)}
        return tcpdumps_dict

    def _attempt_ssh_client_login(self, ssh_client, ssh_username, ssh_password, ssh_prompt):
        for i in range(0, 3):
            try:
                # if 'look_for_keys' in ssh_client.login.func_code.co_varnames:
                if 'look_for_keys' in ssh_client.login.__code__.co_varnames:
                    ssh_client.login(ssh_username, ssh_password, look_for_keys=True)
                else:
                    ssh_client.login(ssh_username, ssh_password)
                return ssh_client
            except Exception as e:
                sleep(1)
                continue
        raise Exception

    def _out_of_scope(self):
        """Method will define set of actions to clean-up library."""
        for key in self.store.aliases:
            self.teardown_tcpdump(alias=key)
